head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf91110";
scwin.div_redmpt = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — crtvlList, debtRepayRankTpList, codCapSecuTpList, bkHoldyDdIntPayDecsnCdList, coupnPayMethdCdList, bndIntPayDdBasTpCdList, bndSaleTpCdList, cfiCdGroupList, stdCdApctTpCdList, callList, putList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.div_redmpt = $c.util.getComponent('div_redmpt');
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_datefmt_cal_isuDd();
        scwin.init_datefmt_cal_redmptDd();
        scwin.init_datefmt_cal_fstIntPayDd();
        scwin.init_datefmt_cal_saleDd();
        scwin.init_datefmt_cal_grtYdStrtDd();
        scwin.init_datefmt_cal_addYdStrtDd();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91110.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_cd", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9201'); } }, { id: "if_cd_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9202'); } }, { id: "if_cd_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9203'); } }, { id: "if_cd_4", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9204'); } }, { id: "c_when_19", fn: function(){ return (!(String(((dma_pageContext.get("crtvlList") ?? "")) == null ? '' : ((dma_pageContext.get("crtvlList") ?? ""))).length === 0)); } }, { id: "txt_strong130", fn: function(){ return ((dma_map.get("nusualBndTpCd") ?? (() => { throw new Error("unresolved:" + "map.nusualBndTpCd"); })()) ==='2'); } }, { id: "rd_debtRepayRankTpCd", fn: function(){ return (!(String(((dma_pageContext.get("debtRepayRankTpList") ?? "")) == null ? '' : ((dma_pageContext.get("debtRepayRankTpList") ?? ""))).length === 0)); } }, { id: "rd_condCapSecuTpCd", fn: function(){ return (!(String(((dma_pageContext.get("codCapSecuTpList") ?? "")) == null ? '' : ((dma_pageContext.get("codCapSecuTpList") ?? ""))).length === 0)); } }, { id: "if_asstSecutizTpNm_txt", fn: function(){ return ((dma_map.get("asstSecutizTpNm") ?? (() => { throw new Error("unresolved:" + "map.asstSecutizTpNm"); })()) === ''); } }, { id: "rd_bkHoldyPrincPayDdDecsnCd", fn: function(){ return (!(String(((dma_pageContext.get("bkHoldyDdIntPayDecsnCdList") ?? "")) == null ? '' : ((dma_pageContext.get("bkHoldyDdIntPayDecsnCdList") ?? ""))).length === 0)); } }, { id: "rd_bkHoldyDdIntPayMethdCd", fn: function(){ return (!(String(((dma_pageContext.get("bkHoldyDdIntPayDecsnCdList") ?? "")) == null ? '' : ((dma_pageContext.get("bkHoldyDdIntPayDecsnCdList") ?? ""))).length === 0)); } }, { id: "rd_coupnPayMethdCd", fn: function(){ return (!(String(((dma_pageContext.get("coupnPayMethdCdList") ?? "")) == null ? '' : ((dma_pageContext.get("coupnPayMethdCdList") ?? ""))).length === 0)); } }, { id: "rd_bndIntPayDdBasTpCd", fn: function(){ return (!(String(((dma_pageContext.get("bndIntPayDdBasTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("bndIntPayDdBasTpCdList") ?? ""))).length === 0)); } }, { id: "c_when_452", fn: function(){ return ((dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })()) === 'GB035'); } }, { id: "div_presale", fn: function(){ return ((dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })()) === 'GB035'); } }, { id: "rd_bndSaleTpCd", fn: function(){ return (!(String(((dma_pageContext.get("bndSaleTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("bndSaleTpCdList") ?? ""))).length === 0)); } }, { id: "rd_group", fn: function(){ return (!(String(((dma_pageContext.get("cfiCdGroupList") ?? "")) == null ? '' : ((dma_pageContext.get("cfiCdGroupList") ?? ""))).length === 0)); } }, { id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }, { id: "c_when_807", fn: function(){ return (!(String(((dma_pageContext.get("callList") ?? "")) == null ? '' : ((dma_pageContext.get("callList") ?? ""))).length === 0)); } }, { id: "c_when_817", fn: function(){ return (!(String(((dma_pageContext.get("putList") ?? "")) == null ? '' : ((dma_pageContext.get("putList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb4", fn: function () { return String(dma_map.get("bndClssNm")) + " (" + String(dma_map.get("bndClssCd")) + ")"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

