/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.num.numberToKor($c.util.getComponent('ipt_isuAmt').getValue(), 'amt_str');
        $c.num.formatNumber($("#ipt_isuAmt")[0]);
        scwin.set_coupn_rt($c.util.getComponent('ipt_coupnRtFinalYn2').getValue());
        scwin.set_isu_dd_ref_idx($c.util.getComponent('ipt_infllnkYn1').getValue());
        if (($c.util.getComponent('ipt_intPayUnitMms').getValue() == null ? '' : String($c.util.getComponent('ipt_intPayUnitMms').getValue())) === '') {
            scwin.set_bnd_oddllotdd_int_bas_tp_cd("");
        } else {
            scwin.set_bnd_oddllotdd_int_bas_tp_cd("1");
        }
        scwin.setBnd_sale_tp_cd();
        if (($c.util.getComponent('slc_byinstCreditValuGrd1').getValue() == null ? '' : String($c.util.getComponent('slc_byinstCreditValuGrd1').getValue())) !== '') {
            (($c.util.getComponent('ipt_creditValuInstCd1')) && ($c.util.getComponent('ipt_creditValuInstCd1')).setValue ? ($c.util.getComponent('ipt_creditValuInstCd1')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
            scwin.crdtVal($("#ipt_creditValuInstCd1")[0]);
        }
        if (($c.util.getComponent('slc_byinstCreditValuGrd2').getValue() == null ? '' : String($c.util.getComponent('slc_byinstCreditValuGrd2').getValue())) !== '') {
            (($c.util.getComponent('ipt_creditValuInstCd2')) && ($c.util.getComponent('ipt_creditValuInstCd2')).setValue ? ($c.util.getComponent('ipt_creditValuInstCd2')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
            scwin.crdtVal($("#ipt_creditValuInstCd2")[0]);
        }
        if (($c.util.getComponent('slc_byinstCreditValuGrd3').getValue() == null ? '' : String($c.util.getComponent('slc_byinstCreditValuGrd3').getValue())) !== '') {
            (($c.util.getComponent('ipt_creditValuInstCd3')) && ($c.util.getComponent('ipt_creditValuInstCd3')).setValue ? ($c.util.getComponent('ipt_creditValuInstCd3')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
            scwin.crdtVal($("#ipt_creditValuInstCd3")[0]);
        }
        if (($c.util.getComponent('slc_byinstCreditValuGrd4').getValue() == null ? '' : String($c.util.getComponent('slc_byinstCreditValuGrd4').getValue())) !== '') {
            (($c.util.getComponent('ipt_creditValuInstCd4')) && ($c.util.getComponent('ipt_creditValuInstCd4')).setValue ? ($c.util.getComponent('ipt_creditValuInstCd4')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
            scwin.crdtVal($("#ipt_creditValuInstCd4")[0]);
        }
        scwin.setCfi();
        scwin.checkRegData();
        $c.util.getComponent("cal_isuDd").setValue($c.date.dateFormat($c.util.getComponent('cal_isuDd').getValue()));
        $c.util.getComponent("cal_redmptDd").setValue($c.date.dateFormat($c.util.getComponent('cal_redmptDd').getValue()));
        $c.util.getComponent("cal_fstIntPayDd").setValue($c.date.dateFormat($c.util.getComponent('cal_fstIntPayDd').getValue()));
        $c.util.getComponent("cal_saleDd").setValue($c.date.dateFormat($c.util.getComponent('cal_saleDd').getValue()));
        $c.util.getComponent("cal_grtYdStrtDd").setValue($c.date.dateFormat($c.util.getComponent('cal_grtYdStrtDd').getValue()));
        $c.util.getComponent("cal_addYdStrtDd").setValue($c.date.dateFormat($c.util.getComponent('cal_addYdStrtDd').getValue()));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91110.onpageload' }); }
};

