 */
scwin.Chk_Number_Plus = async function (Name) {
    if (!scwin.Chk_Digit_Plus(Name.value)) {
        await $c.win.alert(" 숫자만 입력 가능합니다.");
        Name.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name Chk_Digit_Plus
 * @description Chk Digit Plus 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.Chk_Digit_Plus = function (str) {
    for (let i = 0; i < str.length; i++) {
        const ch = str.charAt(i);
        if ((ch < "0" || ch > "9")) {
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkRegData
 * @description check Reg Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRegData = function () {
    let std_cd_apct_tp_cd = $c.util.getComponent('ipt_stdCdApctTpCd').getValue(); if (std_cd_apct_tp_cd == null) { std_cd_apct_tp_cd = ''; }
    if (std_cd_apct_tp_cd !== '') {
        const tObj = $('input[name=std_cd_apct_tp_cd][value="' + std_cd_apct_tp_cd + '"]');
        if (tObj.length > 0) {
            $(tObj)[0].checked = true;
        }
    }
    let encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail').getValue(); if (encryp_apct_email == null) { encryp_apct_email = ''; }
    if (encryp_apct_email !== '') {
        const emails = encryp_apct_email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_encrypApctEmail1').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_encrypApctEmail2').setValue(emails[1]);
        }
    }
    let apct_tel_no = $c.util.getComponent('ipt_apctTelNo').getValue(); if (apct_tel_no == null) { apct_tel_no = ''; }
    if (apct_tel_no !== '') {
        const tels = apct_tel_no.split("-");
        if (tels.length > 0) {
            if (tels.length === 3) {
                $c.util.getComponent('ipt_apctTelNo1').setValue(tels[0]);
                $c.util.getComponent('ipt_apctTelNo2').setValue(tels[1]);
                $c.util.getComponent('ipt_apctTelNo3').setValue(tels[2]);
            }
            if (tels.length === 2) {
                $c.util.getComponent('ipt_apctTelNo2').setValue(tels[0]);
                $c.util.getComponent('ipt_apctTelNo3').setValue(tels[1]);
            }
        }
    }
    let apct_fax_no = $c.util.getComponent('ipt_apctFaxNo').getValue(); if (apct_fax_no == null) { apct_fax_no = ''; }
    if (apct_fax_no !== '') {
        const faxs = apct_fax_no.split("-");
        if (faxs.length > 0) {
            if (faxs.length === 3) {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(faxs[0]);
                $c.util.getComponent('ipt_apctFaxNo2').setValue(faxs[1]);
                $c.util.getComponent('ipt_apctFaxNo3').setValue(faxs[2]);
            }
            if (faxs.length === 2) {
                $c.util.getComponent('ipt_apctFaxNo2').setValue(faxs[0]);
                $c.util.getComponent('ipt_apctFaxNo3').setValue(faxs[1]);
            }
        }
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
};

