scwin.open_select_inst_cd = function (id) {
    const formName = (document.JLDINF91110 || { elements: [] });
    if (id === 1) {
        fn_popupInstCdFirstSearch(formName, "grtInstCd", "grtInstNm", id);
    } else {
        if (id === 2) {
            fn_popupInstCdFirstSearch(formName, "princintPayAgntCd", "princintPayAgntNm", id);
        } else {
            if (id === 3) {
                fn_popupInstCdFirstSearch(formName, "regInstCd", "regInstNm", id);
            } else {
                if (id === 5) {
                    fn_popupInstCdFirstSearch(formName, "bndMajagntComCd", "bndMajagntComNm", id);
                }
            }
        }
    }
    return;
};

