        } else {
            if (bTmp === "2" || bTmp === "5") {
                (($c.util.getComponent('ipt_grtRt')) && ($c.util.getComponent('ipt_grtRt')).setReadOnly ? ($c.util.getComponent('ipt_grtRt')).setReadOnly((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
                $c.util.getComponent("ipt_grtRt").setStyle("background", "");
                $c.util.getComponent('ipt_grtRt').setValue("");
            } else {
                $c.util.getComponent('ipt_grtRt').setValue("");
                (($c.util.getComponent('ipt_grtRt')) && ($c.util.getComponent('ipt_grtRt')).setReadOnly ? ($c.util.getComponent('ipt_grtRt')).setReadOnly((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                $c.util.getComponent("ipt_grtRt").setStyle("background", "#e2e2e2");
            }
        }
    }
    if (bTmp === '4') {
        const rankTmp = $('input[name=debt_repay_rank_tp_cd]:checked').val();
        if (rankTmp === '1') {
            $c.util.getComponent('slc_attr02').setValue("N");
        } else {
