                    $c.util.getComponent('slc_attr02').setValue("Q");
                } else {
                    if (rankTmp === '4') {
                        $c.util.getComponent('slc_attr02').setValue("J");
                    }
                }
            }
        }
    }
    scwin.chk_cfi();
};

