/**
 * @method
 * @name makeFisn
 * @description make Fisn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeFisn = async function () {
    $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));
    const thisForm = $('#JLDINF91110');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    let temp = "";
    temp += $c.util.getComponent('ipt_comEngAbbrv').getValue();
    const sTmp = '' + dma_map.get("int_pay_methd_cd") + '';
    if (sTmp === "11") {
        temp += "/Disc";
    } else {
        if (sTmp === "12" || sTmp === "13" || sTmp === "14" || sTmp === "15" || sTmp === "19") {
            if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) > 0) {
                temp += "/" + $c.util.getComponent('ipt_coupnRt').getValue();
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) === 0) {
                    temp += "/";
                }
            }
        } else {
            if (sTmp === "21" || sTmp === "22" || sTmp === "23" || sTmp === "29") {
                temp += "/Vari";
            }
        }
    }
    const groupTmp = $('input[name=group]:checked').val();
    if (groupTmp === "B") {
        temp += " Bd";
    } else {
        if (groupTmp === "C") {
            temp += " CV Bd";
        } else {
            if (groupTmp === "W") {
                temp += " Bd Cum Wt";
            } else {
                if (groupTmp === "T") {
                    temp += " MTN";
                } else {
                    if (groupTmp === "G") {
                        temp += " MBS";
                    } else {
                        if (groupTmp === "A") {
                            temp += " ASST BKD";
                        } else {
                            if (groupTmp === "N") {
                                temp += " Mun Bd";
                            }
                        }
                    }
                }
            }
        }
    }
    temp += " " + $c.str.replaceAll($c.util.getComponent('cal_redmptDd').getValue(), "-", "");
    if ($('input[name=debt_repay_rank_tp_cd]:checked').val() === "1") {
        temp += " Sr";
    } else {
        if ($('input[name=debt_repay_rank_tp_cd]:checked').val() === "2") {
            temp += " Sr Sub";
        } else {
            if ($('input[name=debt_repay_rank_tp_cd]:checked').val() === "3") {
                temp += " Jr";
            } else {
                if ($('input[name=debt_repay_rank_tp_cd]:checked').val() === "4") {
                    temp += " Jr Sub";
                }
            }
        }
    }
    if ($c.util.getComponent('slc_bndGuarTpCd').getValue() === "1" || $c.util.getComponent('slc_bndGuarTpCd').getValue() === "2" || $c.util.getComponent('slc_bndGuarTpCd').getValue() === "5") {
        temp += " Gtd";
    } else {
        if ($c.util.getComponent('slc_bndGuarTpCd').getValue() === "4") {
            temp += " Ungtd";
        } else {
            temp += "";
        }
    }
    $c.util.getComponent('ipt_fisnVal').setValue(fn_cut_spacingWords(temp, 35));
    $c.util.getComponent('ipt_fisnVal').setValue(($c.util.getComponent("ipt_fisnVal").getValue() || '').toUpperCase());
    $c.util.getComponent('ipt_fisnMakeYn').setValue("Y");
};

